class Solution:
    def splitMessage(self, message: str, limit: int) -> list[str]:
        n = len(message)
        cur_sum_len = 0
        for b in range(1, n + 1):
            d = len(str(b))
            cur_sum_len += len(str(b))
            if limit <= d + 3 + d:
                continue
            cap = b * (limit - 3 - d) - cur_sum_len
            if cap >= n:
                ans = []
                idx = 0
                for i in range(1, b + 1):
                    suffix = f"<{i}/{b}>"
                    msg_len = limit - len(suffix)
                    ans.append(message[idx:idx + msg_len] + suffix)
                    idx += msg_len
                return ans
        return []

class Solution {
public:
    std::vector<std::string> splitMessage(std::string message, int limit) {
        int n = message.length();
        int cur_sum_len = 0;
        for (int b = 1; b <= n; ++b) {
            int d = std::to_string(b).length();
            cur_sum_len += d;
            if (limit <= d + 3 + d) continue;
            long long cap = (long long)b * (limit - 3 - d) - cur_sum_len;
            if (cap >= n) {
                std::vector<std::string> ans;
                int idx = 0;
                for (int i = 1; i <= b; ++i) {
                    std::string suffix = "<" + std::to_string(i) + "/" + std::to_string(b) + ">";
                    int msg_len = limit - suffix.length();
                    ans.push_back(message.substr(idx, msg_len) + suffix);
                    idx += msg_len;
                }
                return ans;
            }
        }
        return {};
    }
};

class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        int curSumLen = 0;
        for (int b = 1; b <= n; b++) {
            int d = String.valueOf(b).length();
            curSumLen += d;
            if (limit <= d + 3 + d) continue;
            long cap = (long) b * (limit - 3 - d) - curSumLen;
            if (cap >= n) {
                String[] ans = new String[b];
                int idx = 0;
                for (int i = 1; i <= b; i++) {
                    String suffix = "<" + i + "/" + b + ">";
                    int msgLen = limit - suffix.length();
                    int take = Math.min(msgLen, n - idx);
                    ans[i - 1] = message.substring(idx, idx + take) + suffix;
                    idx += take;
                }
                return ans;
            }
        }
        return new String[0];
    }
}

var splitMessage = function(message, limit) {
    const n = message.length;
    let curSumLen = 0;
    for (let b = 1; b <= n; b++) {
        const d = String(b).length;
        curSumLen += d;
        if (limit <= d + 3 + d) continue;
        const cap = b * (limit - 3 - d) - curSumLen;
        if (cap >= n) {
            const ans = [];
            let idx = 0;
            for (let i = 1; i <= b; i++) {
                const suffix = `<${i}/${b}>`;
                const msgLen = limit - suffix.length;
                ans.push(message.slice(idx, idx + msgLen) + suffix);
                idx += msgLen;
            }
            return ans;
        }
    }
    return [];
};
